(()=>{'use strict';
const STORE='transtrade_export_v2_operational';
const TODAY=()=>new Date().toLocaleDateString('en-CA');
const uid=p=>`${p}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number(v||0);
const money=(v,c='USD')=>`${c} ${num(v).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const fmt=d=>{if(!d)return'';const m=String(d).match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?`${m[3]}-${m[2]}-${m[1]}`:d};
const addDays=(iso,n)=>{const d=new Date(`${iso}T12:00:00`);d.setDate(d.getDate()+n);return d.toLocaleDateString('en-CA')};
const addBankDays=(iso,n)=>{let d=new Date(`${iso}T12:00:00`),c=0;while(c<n){d.setDate(d.getDate()+1);if(d.getDay()!==0&&d.getDay()!==6)c++}return d.toLocaleDateString('en-CA')};

const DEFAULT_QUALITY='Free from live insects, bad odour and rice fit for human consumption.';
const PAYMENT_LABELS={ADV_SCAN:'Advance + Balance Against Scan Copies',ADV_CAD:'Advance + Balance CAD',ADV100:'100% Advance',LC_SIGHT:'100% Irrevocable L/C at Sight',LC_USANCE:'Usance L/C',CAD100:'100% CAD',CUSTOM:'Custom Payment Terms'};
const SELLERS={TTI:'TRANSTRADE INTERNATIONAL',BRM:'BRM',TG:'TRANS GRAINS FOODSTUFF TRADING L.L.C'};
function seed(){return {version:'clean-v1',customers:[{id:'C-DAYA',name:'Daya General Trading LLC',code:'DM',address:'Dubai, UAE',country:'UAE',packingDefault:'KG',nextSeq:3}],suppliers:[{id:'SUP-ALEEM',name:'Aleem Bags'}],fi:[],contracts:[],shipments:[],millSync:{newExportBags:[],productionInstructions:[],exportLoading:[]},audits:[],alerts:[],settings:{}}}
function normalize(x){x=x&&typeof x==='object'?x:seed();x.version='clean-v1';for(const k of ['customers','suppliers','fi','contracts','shipments','audits','alerts'])x[k]=Array.isArray(x[k])?x[k]:[];x.millSync=x.millSync||{};for(const k of ['newExportBags','productionInstructions','exportLoading'])x.millSync[k]=Array.isArray(x.millSync[k])?x.millSync[k]:[];if(!x.customers.length)x.customers=seed().customers;if(!x.suppliers.length)x.suppliers=seed().suppliers;return x}
function load(){try{return normalize(JSON.parse(localStorage.getItem(STORE)||'null'))}catch{return seed()}}
let state=load(), view='home', currentShipmentId='', activeWorkspace='', contractDraft=null, contractStep=1, modalStack=[];
function save(){localStorage.setItem(STORE,JSON.stringify(state));const b=document.getElementById('saveBadge');if(b)b.textContent=`Saved ${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`}
function audit(area,action,detail=''){state.audits.unshift({at:new Date().toISOString(),user:window.TT_MODULE_ACCESS?.user||'User',area,action,detail});save()}
const contractByRef=ref=>state.contracts.find(c=>c.ref===ref);
const shipment=()=>state.shipments.find(s=>s.id===currentShipmentId);
const customer=id=>state.customers.find(c=>c.id===id);

function mount(){document.getElementById('app').innerHTML=`<div class="shell"><div class="topbar"><h1>TRANSTRADE EXPORTS — CLEAN V1</h1><span class="status green">NEW CLEAN CODEBASE</span><div class="meta"><span id="saveBadge">Ready</span></div></div><div class="nav" id="nav"></div><main id="main"></main></div>`;render()}
function render(){renderNav();if(view==='home')renderHome();else if(view==='contracts')renderContracts();else if(view==='shipments')renderShipments();else if(view==='fi')renderFI();else if(view==='reports')renderReports()}
function renderNav(){const items=[['home','Home'],['contracts','Sales Contracts'],['shipments','Shipments'],['fi','FI Register'],['reports','Reports & Registers']];document.getElementById('nav').innerHTML=items.map(([k,l])=>`<button class="${view===k?'active':''}" data-nav="${k}">${l}</button>`).join('');document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;activeWorkspace='';render()})}
function renderHome(){const active=state.shipments.filter(s=>!s.cancelled&&!s.completed);document.getElementById('main').innerHTML=`<div class="panel"><div class="toolbar"><div><h2>Export Operations</h2><div class="metaText">Clean rebuild. One renderer per screen, one event path, one state model.</div></div><div class="spacer"></div><button class="btn green" id="newContract">+ NEW SALES CONTRACT</button></div></div><div class="cards">${active.map(s=>shipmentCard(s)).join('')||'<div class="panel">No active shipments.</div>'}</div>`;document.getElementById('newContract').onclick=()=>startContract();wireShipmentCards()}
function shipmentCard(s){const c=contractByRef(s.contractRef)||{};return `<div class="card" data-ship="${esc(s.id)}"><b>${esc(s.contractRef)}</b><div class="metaText">${esc(s.buyer)} · ${num(s.plannedQty).toFixed(3)} MT · ${esc(c.product||'')}</div><div style="margin-top:8px"><span class="status ${s.status==='Contract Received'?'green':'amber'}">${esc(s.status||'Planning')}</span></div></div>`}
function wireShipmentCards(){document.querySelectorAll('[data-ship]').forEach(x=>x.onclick=()=>openShipment(x.dataset.ship))}
function renderContracts(){document.getElementById('main').innerHTML=`<div class="panel"><div class="toolbar"><h2>Sales Contracts</h2><div class="spacer"></div><button class="btn green" id="newContract">+ NEW SALES CONTRACT</button></div><div class="tableWrap"><table class="table"><thead><tr><th>Ref</th><th>Date</th><th>Buyer</th><th>Product</th><th>Qty MT</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody>${state.contracts.map(c=>`<tr><td>${esc(c.ref)}</td><td>${fmt(c.date)}</td><td>${esc(customer(c.customerId)?.name||c.customer||'')}</td><td>${esc(c.product)}</td><td>${num(c.qty).toFixed(3)}</td><td>${esc(PAYMENT_LABELS[c.paymentCode]||c.paymentText||'')}</td><td>${esc(c.status)}</td><td><button class="btn small soft" data-contract="${esc(c.id)}">Open / Amend</button></td></tr>`).join('')}</tbody></table></div></div>`;document.getElementById('newContract').onclick=()=>startContract();document.querySelectorAll('[data-contract]').forEach(b=>b.onclick=()=>openContract(b.dataset.contract))}
function nextContractRef(custId,seller='TTI'){const cu=customer(custId)||state.customers[0];return `${seller}/${cu.code||'CUS'}/${String(cu.nextSeq||1).padStart(2,'0')}`}
function newContractShape(){const cu=state.customers[0],date=TODAY();return {id:uid('CT'),ref:nextContractRef(cu.id),seller:'TTI',customerId:cu.id,date,product:'IRRI-6 White Rice',broken:5,finish:'Silky Polished & Sortexed',quality:DEFAULT_QUALITY,specMode:'Pakistan Origin Standard',specRows:[],containers:0,weightPer:27,qty:0,tolerance:5,pol:'Karachi Port, Pakistan or Port Qasim, Pakistan',shipmentDate:'',podPort:'',podCountry:'',destPort:'',destCountry:'',packingUnit:cu.packingDefault||'KG',packings:[],currency:'USD',incoterm:'FOB',inspection:'None',insurance:"Buyer's Account",paymentCode:'ADV_SCAN',advancePct:20,usanceDays:90,customPayment:'',paymentText:'',signedDeadline:addDays(date,2),paymentDeadline:addBankDays(date,4),docs:[],terms:[],status:'Draft',issued:false,received:false,versions:[]}}
function startContract(){contractDraft=newContractShape();contractStep=1;view='contracts';renderContractEditor()}
function openContract(id){const c=state.contracts.find(x=>x.id===id);if(!c)return;contractDraft=structuredClone(c);contractStep=1;renderContractEditor()}
function contractValue(){return contractDraft.packings.reduce((a,p)=>a+num(p.containers)*num(p.weightPer)*num(p.price),0)}
function syncQty(){contractDraft.qty=num(contractDraft.containers)*num(contractDraft.weightPer)}
function paymentText(c=contractDraft){if(c.paymentCode==='LC_SIGHT')return 'BY A WORKABLE AND IRREVOCABLE 100% L/C AT SIGHT FROM A FIRST-CLASS BANK ACCEPTABLE TO THE SELLER, AVAILABLE FOR NEGOTIATION THROUGH THE SELLER’S NOMINATED / ACCEPTABLE BANK.';if(c.paymentCode==='LC_USANCE')return `BY IRREVOCABLE USANCE L/C PAYABLE ${num(c.usanceDays)||90} DAYS FROM B/L DATE, WITH NEGOTIATION AND/OR ACCEPTANCE THROUGH THE SELLER’S NOMINATED / ACCEPTABLE BANK.`;if(c.paymentCode==='CUSTOM')return c.customPayment||'';if(c.paymentCode==='ADV100')return '100% ADVANCE PAYMENT.';if(c.paymentCode==='CAD100')return '100% CASH AGAINST DOCUMENTS (CAD).';if(c.paymentCode==='ADV_CAD')return `${num(c.advancePct)}% ADVANCE + BALANCE CASH AGAINST DOCUMENTS (CAD).`;return `${num(c.advancePct)}% ADVANCE + BALANCE AGAINST SCAN COPIES.`}
function renderContractEditor(){view='contracts';document.getElementById('main').innerHTML=`<div class="panel"><div class="toolbar"><div><h2>Sales Contract</h2><div class="metaText">${esc(contractDraft.ref)} · ${esc(contractDraft.status)}</div></div><div class="spacer"></div><button class="btn" id="closeContract">Close</button></div><div class="steps">${['Buyer & Reference','Product','Quantity & Shipment','Packing','PRICE','Payment Terms','Documents / Validity','Review'].map((x,i)=>`<div class="step ${contractStep===i+1?'active':''}" data-step="${i+1}">${i+1}. ${x}</div>`).join('')}</div><div id="contractBody"></div><div class="toolbar" style="margin-top:12px"><button class="btn" id="backStep" ${contractStep===1?'disabled':''}>← Back</button><div class="spacer"></div>${contractStep<8?'<button class="btn green" id="nextStep">Next →</button>':'<button class="btn navy" id="saveContract">SAVE CONTRACT</button><button class="btn green" id="issueContract">SAVE / PRINT PDF</button>'}</div></div>`;renderContractStep();document.querySelectorAll('[data-step]').forEach(x=>x.onclick=()=>{contractStep=num(x.dataset.step);renderContractEditor()});document.getElementById('closeContract').onclick=()=>{contractDraft=null;renderContracts()};document.getElementById('backStep').onclick=()=>{contractStep--;renderContractEditor()};if(contractStep<8)document.getElementById('nextStep').onclick=()=>{const err=validateContractStep(contractStep);if(err)return alert(err);contractStep++;renderContractEditor()};else{document.getElementById('saveContract').onclick=()=>saveContract(false);document.getElementById('issueContract').onclick=()=>saveContract(true)}}
function renderContractStep(){const b=document.getElementById('contractBody');const c=contractDraft,cu=customer(c.customerId)||state.customers[0];if(contractStep===1)b.innerHTML=`<div class="grid2"><div class="field"><label>Selling Entity</label><select id="cSeller">${Object.keys(SELLERS).map(k=>`<option value="${k}" ${c.seller===k?'selected':''}>${k} — ${SELLERS[k]}</option>`).join('')}</select></div><div class="field"><label>Customer</label><div class="toolbar"><select id="cCustomer" style="flex:1">${state.customers.map(x=>`<option value="${x.id}" ${c.customerId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button class="btn small green" id="addCustomer">+ Customer</button></div></div><div class="field"><label>Contract Reference</label><input id="cRef" value="${esc(c.ref)}"></div><div class="field"><label>Contract Date</label><input id="cDate" type="date" value="${c.date}"></div><div class="field full"><label>Buyer Address</label><textarea readonly>${esc(cu.address||'')}</textarea></div></div>`;else if(contractStep===2)b.innerHTML=`<div class="grid2"><div class="field"><label>Product / Variety</label><select id="cProduct">${['IRRI-6 White Rice','IRRI-6 Parboiled Rice','C-9 White Rice','PK-386 White Rice','Super Kernel Basmati','D-98 White Rice','1121 White Rice'].map(x=>`<option ${c.product===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Broken % MAX</label><input id="cBroken" type="number" value="${c.broken}"></div><div class="field"><label>Processing / Finish</label><input id="cFinish" value="${esc(c.finish)}"></div><div class="field"><label>Specifications</label><select id="cSpecMode"><option ${c.specMode==='Pakistan Origin Standard'?'selected':''}>Pakistan Origin Standard</option><option ${c.specMode==='Contract Specific'?'selected':''}>Contract Specific</option></select></div><div class="field full"><label>Additional Quality / Specifications</label><textarea id="cQuality">${esc(c.quality||DEFAULT_QUALITY)}</textarea></div>${c.specMode==='Contract Specific'?`<div class="full" id="specRows">${specRowsHTML()}</div>`:''}</div>`;else if(contractStep===3)b.innerHTML=`<div class="grid4"><div class="field"><label>No. Containers</label><input id="cContainers" type="number" value="${c.containers||''}"></div><div class="field"><label>Weight / Container MT</label><input id="cWeightPer" type="number" step="0.001" value="${c.weightPer||''}"></div><div class="field"><label>Total Quantity MT</label><input id="cQty" readonly value="${num(c.qty).toFixed(3)}"></div><div class="field"><label>Quantity Tolerance ±%</label><input id="cTolerance" type="number" value="${c.tolerance}"></div><div class="field"><label>Latest Shipment Date</label><input id="cShipmentDate" type="date" value="${c.shipmentDate||''}"></div><div class="field"><label>Port of Loading</label><input id="cPOL" value="${esc(c.pol)}"></div><div class="field"><label>Port of Discharge</label><input id="cPOD" value="${esc(c.podPort)}"></div><div class="field"><label>Country</label><input id="cPODCountry" value="${esc(c.podCountry)}"></div><div class="field"><label>Final Destination / Place</label><input id="cDest" value="${esc(c.destPort)}"></div><div class="field"><label>Destination Country</label><input id="cDestCountry" value="${esc(c.destCountry)}"></div></div>`;else if(contractStep===4)b.innerHTML=`<div class="toolbar"><h3>Packing</h3><div class="spacer"></div><div class="field" style="min-width:160px"><label>Packing Unit</label><select id="cPackingUnit"><option ${c.packingUnit==='KG'?'selected':''}>KG</option><option ${c.packingUnit==='LB'?'selected':''}>LB</option></select></div><button class="btn green" id="addPacking">+ ADD PACKING</button></div><div id="packingList">${packingListHTML()}</div>`;else if(contractStep===5)b.innerHTML=`<div class="grid4"><div class="field"><label>Currency</label><select id="cCurrency">${['USD','EUR','GBP','AED','PKR'].map(x=>`<option ${c.currency===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Incoterm</label><select id="cIncoterm">${['FOB','CFR','CIF'].map(x=>`<option ${c.incoterm===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Insurance</label><select id="cInsurance"><option ${c.insurance==="Buyer's Account"?'selected':''}>Buyer's Account</option><option ${c.insurance==="Seller's Account"?'selected':''}>Seller's Account</option></select></div><div class="field"><label>Inspection</label><input id="cInspection" value="${esc(c.inspection)}"></div></div><div id="priceLines">${priceLinesHTML()}</div><div class="notice"><b>Total Contract Value:</b> <span id="contractValue" class="amount">${money(contractValue(),c.currency)}</span></div>`;else if(contractStep===6)b.innerHTML=`<div class="grid2"><div class="field"><label>Payment Terms</label><select id="cPayment">${Object.entries(PAYMENT_LABELS).map(([k,v])=>`<option value="${k}" ${c.paymentCode===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div id="paymentDynamic">${paymentDynamicHTML()}</div></div><div class="notice" id="paymentPreview">${esc(paymentText(c))}</div>`;else if(contractStep===7)b.innerHTML=`<div class="grid2"><div class="field"><label>Signed / Stamped Contract Latest By</label><input id="cSignedDeadline" type="date" value="${c.signedDeadline||''}"></div><div class="field"><label>${c.paymentCode.startsWith('LC_')?'L/C':'Advance / Payment'} Latest By</label><input id="cPaymentDeadline" type="date" value="${c.paymentDeadline||''}"></div><div class="field full"><label>Documents to be Presented</label><textarea id="cDocs">${esc((c.docs||[]).join('\n'))}</textarea></div><div class="field full"><label>Other Terms</label><textarea id="cTerms">${esc((c.terms||[]).join('\n'))}</textarea></div></div>`;else b.innerHTML=reviewContractHTML();wireContractStep()}
function specRowsHTML(){const rows=contractDraft.specRows.length?contractDraft.specRows:[{name:'Broken',value:`${contractDraft.broken}% MAX`},{name:'Moisture',value:''},{name:'Chalky',value:''},{name:'Damaged / Yellow',value:''}];contractDraft.specRows=rows;return `<div class="section"><div class="toolbar"><h3>Contract Specific Specifications</h3><div class="spacer"></div><button class="btn small green" id="addSpec">+ Specification</button></div>${rows.map((r,i)=>`<div class="grid2" style="margin-bottom:7px"><input data-spec-name="${i}" value="${esc(r.name)}"><div class="toolbar"><input style="flex:1" data-spec-value="${i}" value="${esc(r.value)}"><button class="btn small red" data-remove-spec="${i}">Remove</button></div></div>`).join('')}</div>`}
function packingListHTML(){return contractDraft.packings.length?contractDraft.packings.map((p,i)=>`<div class="section"><div class="toolbar"><div><b>${esc(p.type)} · ${p.size} ${contractDraft.packingUnit} · ${esc(p.brand||'NO BRAND')}</b><div class="metaText">${num(p.containers)} container(s) · ${num(p.weightPer).toFixed(3)} MT/container · Tare ${num(p.tare)} g</div></div><div class="spacer"></div><button class="btn small soft" data-edit-pack="${i}">Edit</button><button class="btn small red" data-remove-pack="${i}">Remove</button></div></div>`).join(''):'<div class="notice warn">No packing entered yet.</div>'}
function priceLinesHTML(){return contractDraft.packings.map((p,i)=>`<div class="section"><b>${esc(p.brand||'Packing '+(i+1))} · ${p.size} ${contractDraft.packingUnit}</b><div class="grid4" style="margin-top:8px"><div class="field"><label>PRICE / MT</label><input data-price="${i}" type="number" step="0.01" value="${p.price||''}"></div>${contractDraft.incoterm!=='FOB'?`<div class="field"><label>Freight / MT</label><input data-freight="${i}" type="number" step="0.01" value="${p.freight||''}"></div>`:''}${contractDraft.incoterm==='CIF'?`<div class="field"><label>Insurance / MT</label><input data-ins="${i}" type="number" step="0.01" value="${p.insurance||''}"></div>`:''}<div class="field"><label>Line Value</label><input readonly value="${money(num(p.containers)*num(p.weightPer)*num(p.price),contractDraft.currency)}"></div></div></div>`).join('')||'<div class="notice warn">Add packing before entering price.</div>'}
function paymentDynamicHTML(){const c=contractDraft;if(['ADV_SCAN','ADV_CAD','ADV100'].includes(c.paymentCode))return `<div class="field"><label>Advance %</label><input id="cAdvance" type="number" value="${c.paymentCode==='ADV100'?100:c.advancePct}" ${c.paymentCode==='ADV100'?'readonly':''}></div>`;if(c.paymentCode==='LC_USANCE')return `<div class="grid2"><div class="field"><label>Usance L/C Days</label><input id="cUsance" type="number" value="${c.usanceDays||90}"></div><div class="field"><label>Total L/C Value</label><input readonly value="${money(contractValue(),c.currency)}"></div></div>`;if(c.paymentCode==='LC_SIGHT')return `<div class="field"><label>Total L/C Value</label><input readonly value="${money(contractValue(),c.currency)}"></div>`;if(c.paymentCode==='CUSTOM')return `<div class="field"><label>Custom Payment Terms</label><textarea id="cCustomPayment">${esc(c.customPayment||'')}</textarea></div>`;return '<div></div>'}
function reviewContractHTML(){const c=contractDraft,cu=customer(c.customerId);return `<div class="grid4"><div class="section"><div class="metaText">Reference</div><b>${esc(c.ref)}</b></div><div class="section"><div class="metaText">Buyer</div><b>${esc(cu?.name||'')}</b></div><div class="section"><div class="metaText">Quantity</div><b>${num(c.qty).toFixed(3)} MT</b></div><div class="section"><div class="metaText">Value</div><b>${money(contractValue(),c.currency)}</b></div></div><div class="section"><b>Payment</b><p>${esc(paymentText(c))}</p></div><div class="section"><b>Packing</b>${contractDraft.packings.map((p,i)=>`<p>${i+1}. ${esc(p.brand)} — ${p.size} ${c.packingUnit} ${esc(p.type)} · ${p.containers} container(s) · ${p.weightPer} MT/container · Tare ${p.tare}g</p>`).join('')}</div>`}
function wireContractStep(){const c=contractDraft;if(contractStep===1){cSeller.onchange=e=>{c.seller=e.target.value;c.ref=nextContractRef(c.customerId,c.seller);renderContractEditor()};cCustomer.onchange=e=>{c.customerId=e.target.value;c.ref=nextContractRef(c.customerId,c.seller);c.packingUnit=customer(c.customerId)?.packingDefault||'KG';renderContractEditor()};cRef.oninput=e=>c.ref=e.target.value;cDate.onchange=e=>{c.date=e.target.value;c.signedDeadline=addDays(c.date,2);c.paymentDeadline=addBankDays(c.date,4)};addCustomer.onclick=()=>openCustomerModal()}else if(contractStep===2){cProduct.onchange=e=>c.product=e.target.value;cBroken.oninput=e=>c.broken=num(e.target.value);cFinish.oninput=e=>c.finish=e.target.value;cQuality.oninput=e=>c.quality=e.target.value;cSpecMode.onchange=e=>{c.specMode=e.target.value;renderContractStep()};document.getElementById('addSpec')?.addEventListener('click',()=>{c.specRows.push({name:'',value:''});renderContractStep()});document.querySelectorAll('[data-spec-name]').forEach(x=>x.oninput=e=>c.specRows[num(x.dataset.specName)].name=e.target.value);document.querySelectorAll('[data-spec-value]').forEach(x=>x.oninput=e=>c.specRows[num(x.dataset.specValue)].value=e.target.value);document.querySelectorAll('[data-remove-spec]').forEach(x=>x.onclick=()=>{c.specRows.splice(num(x.dataset.removeSpec),1);renderContractStep()})}else if(contractStep===3){const live=()=>{c.containers=num(cContainers.value);c.weightPer=num(cWeightPer.value);syncQty();cQty.value=c.qty.toFixed(3)};cContainers.oninput=live;cWeightPer.oninput=live;cTolerance.oninput=e=>c.tolerance=num(e.target.value);cShipmentDate.onchange=e=>c.shipmentDate=e.target.value;cPOL.oninput=e=>c.pol=e.target.value;cPOD.oninput=e=>c.podPort=e.target.value;cPODCountry.oninput=e=>c.podCountry=e.target.value;cDest.oninput=e=>c.destPort=e.target.value;cDestCountry.oninput=e=>c.destCountry=e.target.value}else if(contractStep===4){cPackingUnit.onchange=e=>{c.packingUnit=e.target.value;renderContractStep()};addPacking.onclick=()=>openPackingModal(-1);document.querySelectorAll('[data-edit-pack]').forEach(x=>x.onclick=()=>openPackingModal(num(x.dataset.editPack)));document.querySelectorAll('[data-remove-pack]').forEach(x=>x.onclick=()=>{c.packings.splice(num(x.dataset.removePack),1);renderContractStep()})}else if(contractStep===5){cCurrency.onchange=e=>{c.currency=e.target.value;renderContractStep()};cIncoterm.onchange=e=>{c.incoterm=e.target.value;renderContractStep()};cInsurance.onchange=e=>c.insurance=e.target.value;cInspection.oninput=e=>c.inspection=e.target.value;document.querySelectorAll('[data-price]').forEach(x=>x.oninput=e=>{c.packings[num(x.dataset.price)].price=num(e.target.value);document.getElementById('contractValue').textContent=money(contractValue(),c.currency)});document.querySelectorAll('[data-freight]').forEach(x=>x.oninput=e=>c.packings[num(x.dataset.freight)].freight=num(e.target.value));document.querySelectorAll('[data-ins]').forEach(x=>x.oninput=e=>c.packings[num(x.dataset.ins)].insurance=num(e.target.value))}else if(contractStep===6){cPayment.onchange=e=>{c.paymentCode=e.target.value;if(c.paymentCode==='ADV100')c.advancePct=100;renderContractStep()};document.getElementById('cAdvance')?.addEventListener('input',e=>{c.advancePct=num(e.target.value);paymentPreview.textContent=paymentText(c)});document.getElementById('cUsance')?.addEventListener('input',e=>{c.usanceDays=num(e.target.value);paymentPreview.textContent=paymentText(c)});document.getElementById('cCustomPayment')?.addEventListener('input',e=>{c.customPayment=e.target.value;paymentPreview.textContent=paymentText(c)})}else if(contractStep===7){cSignedDeadline.onchange=e=>c.signedDeadline=e.target.value;cPaymentDeadline.onchange=e=>c.paymentDeadline=e.target.value;cDocs.oninput=e=>c.docs=e.target.value.split('\n').filter(Boolean);cTerms.oninput=e=>c.terms=e.target.value.split('\n').filter(Boolean)}}
function validateContractStep(n){const c=contractDraft;if(n===1&&!c.ref.trim())return'Contract Reference required.';if(n===3&&(c.containers<=0||c.weightPer<=0))return'Enter containers and weight per container.';if(n===4&&!c.packings.length)return'Add at least one packing.';if(n===4){const pc=c.packings.reduce((a,p)=>a+num(p.containers),0),pq=c.packings.reduce((a,p)=>a+num(p.containers)*num(p.weightPer),0);if(Math.abs(pc-c.containers)>.001||Math.abs(pq-c.qty)>.001)return'Packing totals must match contract containers and quantity.'}if(n===5&&c.packings.some(p=>num(p.price)<=0))return'Enter PRICE / MT for every packing.';if(n===6&&c.paymentCode==='CUSTOM'&&!c.customPayment.trim())return'Enter Custom Payment Terms.';return''}
function openCustomerModal(){openModal('Add New Customer',`<div class="grid2"><div class="field"><label>Customer Name</label><input id="mCustName"></div><div class="field"><label>Code</label><input id="mCustCode" maxlength="6"></div><div class="field full"><label>Address</label><textarea id="mCustAddress"></textarea></div><div class="field"><label>Country</label><input id="mCustCountry"></div><div class="field"><label>Default Packing Unit</label><select id="mCustPack"><option>KG</option><option>LB</option></select></div></div>`,`<button class="btn" data-modal-close>Cancel</button><button class="btn green" id="saveNewCustomer">SAVE CUSTOMER & RETURN TO CONTRACT</button>`);saveNewCustomer.onclick=()=>{if(!mCustName.value.trim())return alert('Customer Name required.');const n={id:uid('C'),name:mCustName.value.trim(),code:(mCustCode.value.trim()||'CUS').toUpperCase(),address:mCustAddress.value.trim(),country:mCustCountry.value.trim(),packingDefault:mCustPack.value,nextSeq:1};state.customers.push(n);contractDraft.customerId=n.id;contractDraft.packingUnit=n.packingDefault;contractDraft.ref=nextContractRef(n.id,contractDraft.seller);audit('Customer','Added from Sales Contract',n.name);closeModal();renderContractEditor()}}
function openPackingModal(i){const existing=i>=0?contractDraft.packings[i]:null,p=existing?structuredClone(existing):{type:'PP Bags',size:25,brand:'',tare:80,containers:contractDraft.containers||1,weightPer:contractDraft.weightPer||27,price:0,freight:0,insurance:0,extraBagPct:0};openModal(i>=0?'Amend Packing':'Add Packing',`<div class="grid3"><div class="field"><label>Bag Type</label><input id="mPackType" value="${esc(p.type)}"></div><div class="field"><label>Bag Size</label><input id="mPackSize" type="number" value="${p.size}"></div><div class="field"><label>Brand</label><input id="mPackBrand" value="${esc(p.brand)}"></div><div class="field"><label>Tare Grams</label><input id="mPackTare" type="number" value="${p.tare}"></div><div class="field"><label>Containers</label><input id="mPackContainers" type="number" value="${p.containers}"></div><div class="field"><label>Weight / Container MT</label><input id="mPackWeight" type="number" step="0.001" value="${p.weightPer}"></div><div class="field"><label>Extra Bag % (optional)</label><input id="mPackExtra" type="number" step="0.1" value="${p.extraBagPct||0}"></div></div>`,`<button class="btn" data-modal-close>Cancel</button><button class="btn green" id="savePacking">${i>=0?'SAVE AMENDMENT':'ADD PACKING'}</button>`);savePacking.onclick=()=>{const np={...p,type:mPackType.value.trim(),size:num(mPackSize.value),brand:mPackBrand.value.trim(),tare:num(mPackTare.value),containers:num(mPackContainers.value),weightPer:num(mPackWeight.value),extraBagPct:num(mPackExtra.value)};if(!np.type||np.size<=0||np.containers<=0||np.weightPer<=0)return alert('Complete packing fields.');if(i>=0)contractDraft.packings[i]=np;else contractDraft.packings.push(np);closeModal();renderContractStep()}}
function saveContract(print){const c=structuredClone(contractDraft);c.paymentText=paymentText(c);const idx=state.contracts.findIndex(x=>x.id===c.id);if(idx>=0){c.versions=[...(state.contracts[idx].versions||[]),{at:new Date().toISOString(),snapshot:structuredClone(state.contracts[idx])}];state.contracts[idx]=c;audit('Sales Contract','Amended',c.ref)}else{c.issued=true;c.status='Awaiting Customer Confirmation';state.contracts.push(c);const cu=customer(c.customerId);if(cu)cu.nextSeq=num(cu.nextSeq)+1;state.shipments.push(makeShipment(c));audit('Sales Contract','Created',c.ref)}contractDraft=structuredClone(c);save();if(print)printHTML('SALES CONTRACT',salesContractPrint(c));renderContractEditor()}
function makeShipment(c){return {id:uid('S'),contractRef:c.ref,buyer:customer(c.customerId)?.name||'',seller:c.seller,plannedQty:c.qty,containers:c.containers,status:c.received?'Contract Received':'Awaiting Customer Confirmation',next:'Contract Received',cancelled:false,completed:false,bagOrders:[],bagOrderDraft:null,production:{sentToMill:false,dryOn:'No',craftPaper:'No',dpp:'Yes',inspection:c.inspection||'None',qualityNotes:c.quality||DEFAULT_QUALITY},loading:{lots:[]},millActuals:[],customs:{saved:false,date:TODAY(),invoiceNo:`CI-${c.ref.replace(/\W/g,'-')}`,currency:c.currency,invoiceValue:0,fiAllocations:[],gdRefs:[]},bl:{draftSaved:false,description:c.product||''},commercial:{saved:false,date:TODAY(),rate:c.packings[0]?.price||0},covering:{saved:false,dispatched:false},history:[]}}
function salesContractPrint(c){const cu=customer(c.customerId);return `<div class="printPage"><h1 style="text-align:center">SALES CONTRACT</h1><p><b>Reference:</b> ${esc(c.ref)} &nbsp; <b>Date:</b> ${fmt(c.date)}</p><p><b>Seller:</b> ${esc(SELLERS[c.seller]||c.seller)}</p><p><b>Buyer:</b> ${esc(cu?.name||'')}<br>${esc(cu?.address||'')}</p><h3>QUALITY</h3><p>${esc(c.quality)}</p><p><b>Product:</b> ${esc(c.product)} · ${c.broken}% Broken MAX · ${esc(c.finish)}</p><p><b>Quantity:</b> ${c.qty} MT ±${c.tolerance}%</p><p><b>Shipment:</b> latest ${fmt(c.shipmentDate)}</p><h3>PACKING & PRICE</h3>${c.packings.map(p=>`<p>${esc(p.brand)} — ${p.size} ${c.packingUnit} ${esc(p.type)} · ${p.containers} container(s) · Tare ${p.tare}g · <b>${c.incoterm} ${money(p.price,c.currency)}/MT</b></p>`).join('')}<h3>PAYMENT</h3><p>${esc(paymentText(c))}</p><h3>VALIDITY</h3><p>Signed/stamped copy latest <b>${fmt(c.signedDeadline)}</b>; ${c.paymentCode.startsWith('LC_')?'L/C':'payment'} latest <b>${fmt(c.paymentDeadline)}</b>.</p></div>`}

function renderShipments(){document.getElementById('main').innerHTML=`<div class="panel"><h2>Shipments</h2><div class="cards">${state.shipments.map(s=>shipmentCard(s)).join('')||'No shipments.'}</div></div>`;wireShipmentCards()}
function openShipment(id){currentShipmentId=id;view='shipments';activeWorkspace='contract';renderShipmentWorkspace()}
const WORKSPACES=[['contract','SALES CONTRACT'],['bags','BAG ORDER'],['production','PRODUCTION INSTRUCTIONS'],['loading','LOADING INSTRUCTIONS'],['customs','CUSTOMS DOCUMENTS'],['bl','B/L DOCUMENTS'],['commercial','COMMERCIAL DOCUMENTS'],['cover','BANK COVERING & DISPATCH'],['history','HISTORY & VERSIONS']];
function renderShipmentWorkspace(){const s=shipment(),c=contractByRef(s.contractRef);if(!s||!c)return renderShipments();document.getElementById('main').innerHTML=`<div class="panel"><div class="toolbar"><div><h2>${esc(s.contractRef)}</h2><div class="metaText">${esc(s.buyer)} · ${num(s.plannedQty).toFixed(3)} MT · ${esc(s.status)}</div></div><div class="spacer"></div><button class="btn" id="backShipments">← Shipments</button></div><div class="iconRow">${WORKSPACES.map(([k,l])=>`<button class="workspaceIcon ${activeWorkspace===k?'active':''}" data-workspace="${k}">${l}<small>${workspaceStatus(k,s)}</small></button>`).join('')}</div><div class="workspaceDetail" id="workspaceDetail"></div></div>`;backShipments.onclick=()=>{activeWorkspace='';renderShipments()};document.querySelectorAll('[data-workspace]').forEach(b=>b.onclick=()=>{activeWorkspace=b.dataset.workspace;renderShipmentWorkspace()});renderWorkspaceDetail()}
function workspaceStatus(k,s){if(k==='bags')return `${s.bagOrders.length} PO(s)`;if(k==='production')return s.production.sentToMill?'Sent to Mill':'Pending';if(k==='loading')return `${s.loading.lots.length} lot(s)`;if(k==='customs')return s.customs.saved?'Saved':'Pending';if(k==='bl')return s.bl.draftSaved?'Draft Saved':'Pending';return''}
function renderWorkspaceDetail(){const d=document.getElementById('workspaceDetail');if(activeWorkspace==='contract')renderContractWorkspace(d);else if(activeWorkspace==='bags')renderBagOrder(d);else if(activeWorkspace==='production')renderProduction(d);else if(activeWorkspace==='loading')renderLoading(d);else if(activeWorkspace==='customs')renderCustoms(d);else if(activeWorkspace==='bl')renderBL(d);else if(activeWorkspace==='commercial')renderCommercial(d);else if(activeWorkspace==='cover')renderCover(d);else if(activeWorkspace==='history')renderHistory(d)}
function renderContractWorkspace(d){const c=contractByRef(shipment().contractRef);d.innerHTML=`<div class="section"><div class="toolbar"><div><h3>Sales Contract</h3><div class="metaText">${esc(c.status)} · ${fmt(c.date)}</div></div><div class="spacer"></div><button class="btn soft" id="amendContract">OPEN / AMEND CONTRACT</button><button class="btn green" id="markReceived">${c.received?'CONTRACT RECEIVED ✓':'MARK SIGNED CONTRACT RECEIVED'}</button></div></div>`;amendContract.onclick=()=>openContract(c.id);markReceived.onclick=()=>{c.received=true;c.status='Contract Received';shipment().status='Contract Received';shipment().next='Bag Order / Production';audit('Sales Contract','Signed contract received',c.ref);renderShipmentWorkspace()}}
function bagRequired(p,c){const unitKg=c.packingUnit==='LB'?num(p.size)*0.45359237:num(p.size);return unitKg>0?Math.round(num(p.containers)*num(p.weightPer)*1000/unitKg):0}
function ensureBagDraft(){const s=shipment(),c=contractByRef(s.contractRef);if(!s.bagOrderDraft){s.bagOrderDraft={poNo:`PO-${new Date().getFullYear().toString().slice(-2)}${String(s.bagOrders.length+1).padStart(4,'0')}`,supplier:'',deliverTo:'To Be Advised Later',requiredDate:'',lines:c.packings.map((p,i)=>{const req=bagRequired(p,c),extra=num(p.extraBagPct);return{packingIndex:i,brand:p.brand,type:p.type,size:p.size,unit:c.packingUnit,tare:p.tare,requiredBags:req,extraPct:extra,extraBags:Math.ceil(req*extra/100),totalBags:req+Math.ceil(req*extra/100),artworkName:'',artworkData:'',artworkAttached:false,handle:'No',masterBag:{enabled:false,qty:0,tare:0}}})}}return s.bagOrderDraft}
function renderBagOrder(d){const s=shipment(),c=contractByRef(s.contractRef),po=ensureBagDraft();d.innerHTML=`<div class="section"><div class="toolbar"><div><h3>BAG ORDER</h3><div class="metaText">One PO for all packing lines of this shipment.</div></div><div class="spacer"></div><button class="btn soft" id="newPODraft">Reset Draft</button></div><div class="grid3"><div class="field"><label>PO Number</label><input id="boNo" value="${esc(po.poNo)}"></div><div class="field"><label>Supplier</label><select id="boSupplier"><option value="">Select Supplier</option>${state.suppliers.map(x=>`<option ${po.supplier===x.name?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Deliver To</label><input id="boDeliver" value="${esc(po.deliverTo)}"></div><div class="field"><label>Required Delivery Date</label><input id="boDate" type="date" value="${po.requiredDate||''}"></div></div><div class="tableWrap" style="margin-top:10px"><table class="table"><thead><tr><th>#</th><th>Brand</th><th>Packing</th><th>Tare g</th><th>Required</th><th>Extra %</th><th>Extra Bags</th><th>Total</th><th>Handle</th><th>Master Bag</th><th>Artwork</th></tr></thead><tbody>${po.lines.map((l,i)=>`<tr><td>${i+1}</td><td><input data-bo-brand="${i}" value="${esc(l.brand)}"></td><td>${esc(l.type)} · ${l.size} ${l.unit}</td><td><input style="width:80px" data-bo-tare="${i}" type="number" value="${l.tare}"></td><td>${l.requiredBags.toLocaleString()}</td><td><input style="width:75px" data-bo-extra="${i}" type="number" step="0.1" value="${l.extraPct}"></td><td data-extra-bags="${i}">${l.extraBags.toLocaleString()}</td><td data-total-bags="${i}">${l.totalBags.toLocaleString()}</td><td><select data-bo-handle="${i}"><option ${l.handle==='No'?'selected':''}>No</option><option ${l.handle==='Yes'?'selected':''}>Yes</option></select></td><td><label><input data-bo-master="${i}" type="checkbox" ${l.masterBag?.enabled?'checked':''}> Yes</label></td><td><input data-bo-art="${i}" type="file" accept="image/*,.pdf"><div class="metaText">${esc(l.artworkName||'No file')}</div></td></tr>`).join('')}</tbody></table></div><div class="toolbar" style="margin-top:12px"><div class="notice green" style="margin:0">Delivery Challan must clearly mention BRAND NAME and P.O. NUMBER.</div><div class="spacer"></div><button class="btn green" id="generatePO">GENERATE PO PDF & SEND TO MILL</button></div></div>${s.bagOrders.length?`<div class="section"><h3>Issued POs</h3>${s.bagOrders.map((x,i)=>`<div class="notice"><b>${esc(x.poNo)}</b> · ${esc(x.supplier)} · ${x.lines.length} line(s) <button class="btn small soft" data-load-po="${i}">Update Same PO</button></div>`).join('')}</div>`:''}`;wireBagOrder()}
function wireBagOrder(){const s=shipment(),po=ensureBagDraft();boNo.oninput=e=>po.poNo=e.target.value;boSupplier.onchange=e=>po.supplier=e.target.value;boDeliver.oninput=e=>po.deliverTo=e.target.value;boDate.onchange=e=>po.requiredDate=e.target.value;newPODraft.onclick=()=>{s.bagOrderDraft=null;save();renderShipmentWorkspace()};document.querySelectorAll('[data-bo-brand]').forEach(x=>x.oninput=e=>po.lines[num(x.dataset.boBrand)].brand=e.target.value);document.querySelectorAll('[data-bo-tare]').forEach(x=>x.oninput=e=>po.lines[num(x.dataset.boTare)].tare=num(e.target.value));document.querySelectorAll('[data-bo-extra]').forEach(x=>x.oninput=e=>{const l=po.lines[num(x.dataset.boExtra)];l.extraPct=num(e.target.value);l.extraBags=Math.ceil(l.requiredBags*l.extraPct/100);l.totalBags=l.requiredBags+l.extraBags;document.querySelector(`[data-extra-bags="${x.dataset.boExtra}"]`).textContent=l.extraBags.toLocaleString();document.querySelector(`[data-total-bags="${x.dataset.boExtra}"]`).textContent=l.totalBags.toLocaleString()});document.querySelectorAll('[data-bo-handle]').forEach(x=>x.onchange=e=>po.lines[num(x.dataset.boHandle)].handle=e.target.value);document.querySelectorAll('[data-bo-master]').forEach(x=>x.onchange=e=>po.lines[num(x.dataset.boMaster)].masterBag.enabled=e.target.checked);document.querySelectorAll('[data-bo-art]').forEach(x=>x.onchange=e=>{const f=e.target.files[0],l=po.lines[num(x.dataset.boArt)];if(!f)return;l.artworkName=f.name;l.artworkAttached=true;if(f.type.startsWith('image/')){const r=new FileReader();r.onload=()=>{l.artworkData=r.result;save()};r.readAsDataURL(f)}save()});generatePO.onclick=issuePO;document.querySelectorAll('[data-load-po]').forEach(x=>x.onclick=()=>{s.bagOrderDraft=structuredClone(s.bagOrders[num(x.dataset.loadPo)]);s.bagOrderDraft._updateIndex=num(x.dataset.loadPo);renderShipmentWorkspace()})}
function issuePO(){const s=shipment(),po=ensureBagDraft();if(!po.supplier)return alert('Select Supplier.');if(po.lines.some(l=>!l.brand.trim()))return alert('Every packing line must have a Brand.');if(po.lines.some(l=>!l.artworkAttached))return alert('Attach approved artwork / bag marking for every packing line.');const out=structuredClone(po);out.issuedAt=new Date().toISOString();out.status='Synced to Mill';if(Number.isInteger(po._updateIndex)){const old=s.bagOrders[po._updateIndex];out.poNo=old.poNo;out.versions=[...(old.versions||[]),{at:out.issuedAt,snapshot:structuredClone(old)}];s.bagOrders[po._updateIndex]=out}else{s.bagOrders.push(out)}state.millSync.newExportBags=state.millSync.newExportBags.filter(x=>!(x.contractRef===s.contractRef&&x.poNo===out.poNo));out.lines.forEach((l,i)=>state.millSync.newExportBags.push({contractRef:s.contractRef,poNo:out.poNo,supplier:out.supplier,deliverTo:out.deliverTo,requiredDate:out.requiredDate,line:i+1,brand:l.brand,type:l.type,size:l.size,unit:l.unit,orderedTare:l.tare,requiredBags:l.requiredBags,extraPct:l.extraPct,extraBags:l.extraBags,totalOrdered:l.totalBags,artworkName:l.artworkName,artworkData:l.artworkData,handle:l.handle,masterBag:l.masterBag,status:'Order from Export — Awaiting Receipt'}));audit('BAG ORDER','Generated PO and sent to Mill',out.poNo);s.bagOrderDraft=null;printHTML('PURCHASE ORDER',purchaseOrderPrint(out));renderShipmentWorkspace()}
function purchaseOrderPrint(po){return `<div class="printPage"><div style="border-bottom:3px solid #102a46;padding-bottom:8px;margin-bottom:12px"><h1 style="margin:0;color:#102a46">PURCHASE ORDER</h1></div><table style="width:100%;margin-bottom:12px"><tr><td><b>PO Number:</b> ${esc(po.poNo)}</td><td><b>Order Date:</b> ${fmt((po.issuedAt||'').slice(0,10))}</td></tr><tr><td><b>Supplier:</b> ${esc(po.supplier)}</td><td><b>Required Delivery:</b> ${po.requiredDate?fmt(po.requiredDate):'TO BE ADVISED LATER'}</td></tr><tr><td colspan="2"><b>Deliver To:</b> ${esc(po.deliverTo||'To Be Advised Later')}</td></tr></table><table style="width:100%;border-collapse:collapse;font-size:11px"><thead><tr style="background:#102a46;color:white"><th style="padding:6px">#</th><th>Brand</th><th>Packing</th><th>Tare</th><th>Required</th><th>Extra</th><th>Total</th><th>Handle</th><th>Master Bag</th><th>Artwork</th></tr></thead><tbody>${po.lines.map((l,i)=>`<tr>${[`<b>${i+1}</b>`,esc(l.brand),`${esc(l.type)} · ${l.size} ${l.unit}`,`${l.tare} g`,l.requiredBags.toLocaleString(),`${l.extraPct}% / ${l.extraBags.toLocaleString()}`,l.totalBags.toLocaleString(),esc(l.handle||'No'),l.masterBag?.enabled?`${num(l.masterBag.qty).toLocaleString()} · ${num(l.masterBag.tare)}g`:'No',esc(l.artworkName)].map(x=>`<td style="border:1px solid #ccd5dd;padding:6px">${x}</td>`).join('')}</tr>`).join('')}</tbody></table><div style="margin-top:14px;border:1px solid #16825d;background:#edf9f4;padding:9px"><b>DELIVERY CHALLAN MUST CLEARLY MENTION THE BRAND NAME AND P.O. NUMBER.</b></div></div>`}
function renderProduction(d){const s=shipment(),c=contractByRef(s.contractRef),p=s.production;d.innerHTML=`<div class="section"><div class="toolbar"><div><h3>PRODUCTION INSTRUCTIONS</h3><div class="metaText">Automatically carries Sales Contract + Bag Order information.</div></div><div class="spacer"></div>${p.sentToMill?'<div class="stamp">PRODUCTION INSTRUCTIONS ALREADY SENT</div>':''}</div><div class="grid4"><div class="field"><label>Dry On</label><select id="piDry"><option ${p.dryOn==='No'?'selected':''}>No</option><option ${p.dryOn==='Yes'?'selected':''}>Yes</option></select></div><div class="field"><label>Craft Paper</label><select id="piCraft"><option ${p.craftPaper==='No'?'selected':''}>No</option><option ${p.craftPaper==='Yes'?'selected':''}>Yes</option></select></div><div class="field"><label>DPP</label><select id="piDPP"><option ${p.dpp==='Yes'?'selected':''}>Yes</option><option ${p.dpp==='No'?'selected':''}>No</option></select></div><div class="field"><label>Inspection</label><input id="piInspection" value="${esc(p.inspection||c.inspection)}"></div><div class="field full"><label>Quality / Special Instructions</label><textarea id="piQuality">${esc(p.qualityNotes||c.quality)}</textarea></div></div><div class="tableWrap"><table class="table"><thead><tr><th>Brand</th><th>Product</th><th>Packing</th><th>Containers</th><th>MT</th></tr></thead><tbody>${c.packings.map(pk=>`<tr><td>${esc(pk.brand)}</td><td>${esc(c.product)}</td><td>${pk.size} ${c.packingUnit} ${esc(pk.type)}</td><td>${pk.containers}</td><td>${(pk.containers*pk.weightPer).toFixed(3)}</td></tr>`).join('')}</tbody></table></div><div class="toolbar" style="margin-top:12px"><div class="spacer"></div><button class="btn green" id="sendPI">SEND PRODUCTION INSTRUCTIONS TO MILL</button></div></div>`;piDry.onchange=e=>p.dryOn=e.target.value;piCraft.onchange=e=>p.craftPaper=e.target.value;piDPP.onchange=e=>p.dpp=e.target.value;piInspection.oninput=e=>p.inspection=e.target.value;piQuality.oninput=e=>p.qualityNotes=e.target.value;sendPI.onclick=()=>{if(c.packings.some(pk=>!pk.brand.trim()))return alert('Every required bag brand must be inserted before sending Production Instructions.');p.sentToMill=true;state.millSync.productionInstructions=state.millSync.productionInstructions.filter(x=>x.contractRef!==s.contractRef);state.millSync.productionInstructions.push({contractRef:s.contractRef,product:c.product,packings:structuredClone(c.packings),production:structuredClone(p),sentAt:new Date().toISOString()});audit('PRODUCTION INSTRUCTIONS','Sent to Mill',s.contractRef);renderShipmentWorkspace()}}
function renderLoading(d){const s=shipment(),c=contractByRef(s.contractRef);if(!s.loading.draft)s.loading.draft={lotId:`LOT-${s.loading.lots.length+1}`,loadingDate:TODAY(),containers:c.containers,weightPer:c.weightPer,source:'TTI Rice Mills',type:'TTI',tba:false,emptyBags:0};const l=s.loading.draft,totalMT=num(l.containers)*num(l.weightPer),pk=c.packings[0]||{},unitKg=c.packingUnit==='LB'?num(pk.size)*.45359237:num(pk.size),bagsPer=unitKg?Math.round(num(l.weightPer)*1000/unitKg):0;d.innerHTML=`<div class="section"><h3>LOADING INSTRUCTIONS</h3><div class="grid4"><div class="field"><label>Lot</label><input id="liLot" value="${esc(l.lotId)}"></div><div class="field"><label>Loading Date</label><input id="liDate" type="date" value="${l.tba?'':l.loadingDate||''}" ${l.tba?'disabled':''}><label style="font-weight:500"><input id="liTBA" type="checkbox" ${l.tba?'checked':''}> To Be Advised Later</label></div><div class="field"><label>LOADING FROM</label><input id="liSource" value="${esc(l.source)}"></div><div class="field"><label>Source Type</label><select id="liType"><option ${l.type==='TTI'?'selected':''}>TTI</option><option ${l.type==='Ex-Mill'?'selected':''}>Ex-Mill</option><option ${l.type==='Reprocessing'?'selected':''}>Reprocessing</option></select></div><div class="field"><label>No. Containers</label><input id="liContainers" type="number" value="${l.containers}"></div><div class="field"><label>LOADING PER CONTAINER MTONS</label><input id="liWeight" type="number" step=".001" value="${l.weightPer}"></div><div class="field"><label>LOADING PER CONTAINER BAGS</label><input id="liBagsPer" readonly value="${bagsPer.toLocaleString()}"></div><div class="field"><label>Quantity MT</label><input id="liTotalMT" readonly value="${totalMT.toFixed(3)}"></div><div class="field"><label>TOTAL BAGS TO BE LOADED</label><input id="liTotalBags" readonly value="${(bagsPer*num(l.containers)).toLocaleString()}"></div><div class="field"><label>EMPTY BAGS TO BE LOADED</label><input id="liEmpty" type="number" value="${l.emptyBags||0}"></div></div><div class="notice">Dry On: <b>${esc(s.production.dryOn)}</b> · Craft Paper: <b>${esc(s.production.craftPaper)}</b> · DPP: <b>${esc(s.production.dpp)}</b> · Inspection: <b>${esc(s.production.inspection)}</b></div><div class="toolbar"><div class="spacer"></div><button class="btn green" id="sendLoading">CREATE LOT AND SEND INSTRUCTIONS TO MILL</button></div></div>${s.loading.lots.length?`<div class="section"><h3>Created Lots</h3>${s.loading.lots.map(x=>`<div class="notice"><b>${esc(x.lotId)}</b> · ${x.containers} containers · ${x.totalMT.toFixed(3)} MT · ${esc(x.source)}</div>`).join('')}</div>`:''}`;const live=()=>{l.containers=num(liContainers.value);l.weightPer=num(liWeight.value);l.emptyBags=num(liEmpty.value);const bp=unitKg?Math.round(l.weightPer*1000/unitKg):0;liBagsPer.value=bp.toLocaleString();liTotalMT.value=(l.containers*l.weightPer).toFixed(3);liTotalBags.value=(bp*l.containers).toLocaleString()};liLot.oninput=e=>l.lotId=e.target.value;liDate.onchange=e=>l.loadingDate=e.target.value;liTBA.onchange=e=>{l.tba=e.target.checked;renderShipmentWorkspace()};liSource.oninput=e=>l.source=e.target.value;liType.onchange=e=>l.type=e.target.value;liContainers.oninput=live;liWeight.oninput=live;liEmpty.oninput=live;sendLoading.onclick=()=>{if(!l.tba&&!l.loadingDate)return alert('Loading Date required or mark To Be Advised Later.');if(num(l.containers)<=0||num(l.weightPer)<=0)return alert('Enter containers and loading per container.');const lot={...structuredClone(l),totalMT:num(l.containers)*num(l.weightPer),createdAt:new Date().toISOString(),production:structuredClone(s.production),plan:{allocations:[{name:l.source,type:l.type,containers:num(l.containers),weightPer:num(l.weightPer),emptyBags:num(l.emptyBags),packIndex:0}]}};s.loading.lots.push(lot);state.millSync.exportLoading.push({contractRef:s.contractRef,lotId:lot.lotId,plan:structuredClone(lot.plan),production:structuredClone(s.production),sentAt:new Date().toISOString()});s.loading.draft=null;audit('LOADING INSTRUCTIONS','Created lot and sent to Mill',lot.lotId);renderShipmentWorkspace()}}
function renderCustoms(d){const s=shipment(),c=contractByRef(s.contractRef),x=s.customs;const actualQty=s.millActuals.length?s.millActuals.reduce((a,r)=>a+num(r.netKg),0)/1000:s.plannedQty;d.innerHTML=`<div class="section"><h3>CUSTOMS DOCUMENTS</h3><div class="notice">Custom Invoice is the controlling source; Custom Packing List and Phytosanitary Invoice derive from it.</div><div class="grid3"><div class="field"><label>Invoice No.</label><input id="cuNo" value="${esc(x.invoiceNo)}"></div><div class="field"><label>Document Date</label><input id="cuDate" type="date" value="${x.date||TODAY()}"></div><div class="field"><label>Currency</label><input id="cuCurrency" value="${esc(x.currency||c.currency)}"></div><div class="field"><label>Rate / MT</label><input id="cuRate" type="number" value="${num(x.rate||c.packings[0]?.price)}"></div><div class="field"><label>Quantity MT</label><input id="cuQty" readonly value="${actualQty.toFixed(3)}"></div><div class="field"><label>Invoice Value</label><input id="cuValue" readonly value="${money(actualQty*num(x.rate||c.packings[0]?.price),x.currency||c.currency)}"></div><div class="field full"><label>Description</label><textarea id="cuDesc">${esc(x.description||c.product)}</textarea></div></div><div class="toolbar"><div class="spacer"></div><button class="btn navy" id="saveCustoms">SAVE CUSTOM INVOICE</button><button class="btn green" id="printCustoms">PRINT / SAVE PDF</button></div></div>`;cuNo.oninput=e=>x.invoiceNo=e.target.value;cuDate.onchange=e=>x.date=e.target.value;cuCurrency.oninput=e=>x.currency=e.target.value;cuRate.oninput=e=>{x.rate=num(e.target.value);cuValue.value=money(actualQty*x.rate,x.currency)};cuDesc.oninput=e=>x.description=e.target.value;saveCustoms.onclick=()=>{x.saved=true;x.invoiceValue=actualQty*num(x.rate||c.packings[0]?.price);audit('Customs','Custom Invoice saved',x.invoiceNo);renderShipmentWorkspace()};printCustoms.onclick=()=>printHTML('CUSTOM INVOICE',`<div class="printPage"><h1>CUSTOM INVOICE</h1><p><b>Invoice:</b> ${esc(x.invoiceNo)} &nbsp; <b>Date:</b> ${fmt(x.date)}</p><p><b>Description:</b> ${esc(x.description||c.product)}</p><p><b>Quantity:</b> ${actualQty.toFixed(3)} MT</p><p><b>Value:</b> ${money(actualQty*num(x.rate||c.packings[0]?.price),x.currency||c.currency)}</p></div>`)}
function renderBL(d){const s=shipment(),c=contractByRef(s.contractRef),b=s.bl;b.description=b.description||s.customs.description||c.product;d.innerHTML=`<div class="section"><h3>B/L DOCUMENTS</h3><div class="grid2"><div class="field"><label>B/L No.</label><input id="blNo" value="${esc(b.blNo||'')}"></div><div class="field"><label>On Board Date</label><input id="blDate" type="date" value="${b.onBoardDate||''}"></div><div class="field"><label>Vessel</label><input id="blVessel" value="${esc(b.vessel||'')}"></div><div class="field"><label>Voyage</label><input id="blVoyage" value="${esc(b.voyage||'')}"></div><div class="field full"><label>Description</label><textarea id="blDesc">${esc(b.description)}</textarea></div></div><div class="toolbar"><div class="spacer"></div><button class="btn green" id="saveBL">SAVE B/L DRAFT</button></div></div>`;blNo.oninput=e=>b.blNo=e.target.value;blDate.onchange=e=>b.onBoardDate=e.target.value;blVessel.oninput=e=>b.vessel=e.target.value;blVoyage.oninput=e=>b.voyage=e.target.value;blDesc.oninput=e=>b.description=e.target.value;saveBL.onclick=()=>{if(!b.description.trim())return alert('Description is required.');b.draftSaved=true;audit('B/L Draft','Saved',s.contractRef);renderShipmentWorkspace()}}
function renderCommercial(d){const s=shipment(),c=contractByRef(s.contractRef),x=s.commercial;d.innerHTML=`<div class="section"><h3>COMMERCIAL DOCUMENTS</h3><div class="grid3"><div class="field"><label>Document Date</label><input id="coDate" type="date" value="${x.date||TODAY()}"></div><div class="field"><label>Rate / MT</label><input id="coRate" type="number" value="${x.rate||c.packings[0]?.price||0}"></div><div class="field"><label>Status</label><input readonly value="${x.saved?'Saved':'Draft'}"></div></div><div class="toolbar"><div class="spacer"></div><button class="btn green" id="saveCommercial">SAVE COMMERCIAL INVOICE</button></div></div>`;coDate.onchange=e=>x.date=e.target.value;coRate.oninput=e=>x.rate=num(e.target.value);saveCommercial.onclick=()=>{x.saved=true;audit('Commercial','Commercial Invoice saved',s.contractRef);renderShipmentWorkspace()}}
function renderCover(d){const s=shipment(),x=s.covering;d.innerHTML=`<div class="section"><h3>BANK COVERING & DISPATCH</h3><div class="grid3"><div class="field"><label>Sent Through</label><select id="cvThrough"><option ${x.sentThrough==='Pakistan Bank'?'selected':''}>Pakistan Bank</option><option ${x.sentThrough==='DHL'?'selected':''}>DHL</option><option ${x.sentThrough==='TCS'?'selected':''}>TCS</option><option ${x.sentThrough==='SKYNET'?'selected':''}>SKYNET</option></select></div><div class="field"><label>Dispatch Date</label><input id="cvDate" type="date" value="${x.dispatchDate||''}"></div><div class="field"><label>AWB / Tracking No.</label><input id="cvTrack" value="${esc(x.tracking||'')}"></div></div><div class="toolbar"><div class="spacer"></div><button class="btn green" id="saveCover">SAVE DISPATCH</button></div></div>`;cvThrough.onchange=e=>x.sentThrough=e.target.value;cvDate.onchange=e=>x.dispatchDate=e.target.value;cvTrack.oninput=e=>x.tracking=e.target.value;saveCover.onclick=()=>{x.saved=true;x.dispatched=true;audit('Bank Covering','Dispatch saved',x.tracking);renderShipmentWorkspace()}}
function renderHistory(d){const s=shipment();const rows=state.audits.filter(a=>String(a.detail).includes(s.contractRef)||['Sales Contract','BAG ORDER','PRODUCTION INSTRUCTIONS','LOADING INSTRUCTIONS','Customs','B/L Draft','Commercial','Bank Covering'].includes(a.area));d.innerHTML=`<div class="section"><h3>HISTORY & VERSIONS</h3><div class="tableWrap"><table class="table"><thead><tr><th>When</th><th>User</th><th>Area</th><th>Action</th><th>Detail</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${new Date(a.at).toLocaleString()}</td><td>${esc(a.user)}</td><td>${esc(a.area)}</td><td>${esc(a.action)}</td><td>${esc(a.detail)}</td></tr>`).join('')}</tbody></table></div></div>`}
function renderFI(){document.getElementById('main').innerHTML=`<div class="panel"><div class="toolbar"><h2>FI Register / FI Utilisation</h2><div class="spacer"></div><button class="btn green" id="addFI">+ ADD FI</button></div><div class="tableWrap"><table class="table"><thead><tr><th>FI No.</th><th>Date</th><th>Customer</th><th>Type</th><th>Bank</th><th>Currency</th><th>Total Value</th></tr></thead><tbody>${state.fi.map(f=>`<tr><td>${esc(f.number)}</td><td>${fmt(f.date)}</td><td>${esc(f.customer)}</td><td>${esc(f.type)}</td><td>${esc(f.bank)}</td><td>${esc(f.currency)}</td><td>${money(f.value,f.currency)}</td></tr>`).join('')}</tbody></table></div></div>`;addFI.onclick=()=>openModal('Add FI',`<div class="grid3"><div class="field"><label>FI No.</label><input id="mFINo"></div><div class="field"><label>Date</label><input id="mFIDate" type="date" value="${TODAY()}"></div><div class="field"><label>Customer</label><input id="mFICustomer"></div><div class="field"><label>Type</label><select id="mFIType"><option>Advance</option><option>L/C</option><option>Open Account</option></select></div><div class="field"><label>Bank</label><input id="mFIBank"></div><div class="field"><label>Currency</label><input id="mFICur" value="USD"></div><div class="field"><label>Total Value</label><input id="mFIValue" type="number"></div></div>`,`<button class="btn" data-modal-close>Cancel</button><button class="btn green" id="saveFI">SAVE FI</button>`);setTimeout(()=>{const b=document.getElementById('saveFI');if(b)b.onclick=()=>{if(!mFINo.value.trim())return alert('FI Number required.');state.fi.push({id:uid('FI'),number:mFINo.value.trim(),date:mFIDate.value,customer:mFICustomer.value.trim(),type:mFIType.value,bank:mFIBank.value.trim(),currency:mFICur.value.trim()||'USD',value:num(mFIValue.value),allocations:[]});audit('FI Register','FI added',mFINo.value.trim());closeModal();renderFI()}},0)}
function renderReports(){const rows=state.shipments.flatMap(s=>(s.millActuals||[]).map(a=>`<tr><td>${esc(s.contractRef)}</td><td>${esc(a.number)}</td><td>${esc(a.seal)}</td><td>${esc(a.location)}</td><td>${num(a.bags).toLocaleString()}</td><td>${num(a.netKg).toFixed(3)}</td></tr>`)).join('');document.getElementById('main').innerHTML=`<div class="cards"><div class="panel"><h2>Container / Loading Register</h2><div class="tableWrap"><table class="table"><thead><tr><th>Contract</th><th>Container</th><th>Seal</th><th>Loading From</th><th>Bags</th><th>Net KG</th></tr></thead><tbody>${rows}</tbody></table></div></div><div class="panel"><h2>FI Register / FI Utilisation</h2><button class="btn navy" id="goFI">Open FI Register</button></div></div>`;goFI.onclick=()=>{view='fi';render()}}
function openModal(title,body,foot){const id=uid('modal');modalStack.push(id);const w=document.createElement('div');w.className='modalBackdrop';w.dataset.modal=id;w.innerHTML=`<div class="modal"><div class="modalHead"><h3>${esc(title)}</h3><div style="margin-left:auto"></div><button class="btn small" data-modal-close>✕</button></div><div class="modalBody">${body}</div><div class="modalFoot">${foot||''}</div></div>`;document.body.appendChild(w);w.querySelectorAll('[data-modal-close]').forEach(x=>x.onclick=closeModal);return w}
function closeModal(){const id=modalStack.pop();document.querySelector(`[data-modal="${id}"]`)?.remove()}
function printHTML(title,html){const root=document.getElementById('printRoot');root.innerHTML=html;root.setAttribute('aria-hidden','false');document.title=`${title} - Transtrade`;setTimeout(()=>{window.print();setTimeout(()=>{root.innerHTML='';root.setAttribute('aria-hidden','true')},100)},50)}
window.addEventListener('beforeprint',()=>document.getElementById('printRoot')?.setAttribute('aria-hidden','false'));
window.addEventListener('error',e=>console.error('Transtrade Export Clean V1',e.error||e.message));
mount();
})();
